'use strict';
const consoleActions=new Set();
function coordinatorMap(){return `<svg class="coord-map" viewBox="0 0 1380 795" role="img" aria-label="Illustrative demo map of Beitel and Salado Creek with fictional flooded areas, hosts, residents and cases needing review. Not for navigation."><defs><pattern id="flood-hatch" width="23" height="23" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0V23" stroke="#78a2e8" stroke-width="4"/></pattern></defs><rect width="1380" height="795" fill="#e6edf1"/><g stroke="white" stroke-width="21"><path d="M242 0V795M518 0V795M812 0V795M1106 0V795M0 190H1380M0 570H1380"/></g><path d="M0 389H1380" stroke="#fde68a" stroke-width="31"/><text x="1207" y="377" fill="#85401d" font-size="22" font-weight="750">LOOP 410</text><path d="M0 78C270 158 410 296 644 421S1097 641 1380 684L1380 795C1087 744 822 631 590 493S237 263 0 194Z" fill="#bbd4fa" opacity=".86"/><path d="M0 78C270 158 410 296 644 421S1097 641 1380 684L1380 795C1087 744 822 631 590 493S237 263 0 194Z" fill="url(#flood-hatch)" opacity=".8"/><path d="M0 125C250 186 408 323 630 460S1089 685 1380 739" fill="none" stroke="#3b82f6" stroke-width="19"/><path d="M900-10C926 116 887 254 810 398" fill="none" stroke="#6098f8" stroke-width="12" stroke-linecap="round"/><g fill="#0f7b72" stroke="white" stroke-width="5">${[[363,69],[673,104],[967,104],[1243,138],[1036,259],[138,345],[1278,466],[380,656],[155,691]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="15"/>`).join('')}</g><g fill="#2563eb" stroke="white" stroke-width="5">${[[311,518],[432,483],[725,570],[1070,708]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="12"/>`).join('')}</g><path d="M432 483V570H242V656H346" stroke="#0f7b72" stroke-width="7" stroke-dasharray="3 14" stroke-linecap="round" fill="none"/><g fill="#c33b08" stroke="white" stroke-width="5">${[[605,389],[864,535],[1140,642]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="25"/>`).join('')}</g><g fill="white" font-size="27" font-weight="800" text-anchor="middle"><text x="605" y="398">!</text><text x="864" y="544">!</text><text x="1140" y="651">!</text></g></svg>`;}
function renderCoordinator(){document.documentElement.lang=lang;document.body.classList.add('coordinator-mode');document.title='HighGround · Coordinator console';document.querySelector('.skip').textContent=tx('Skip to main content','Ir al contenido principal');document.querySelector('.close').setAttribute('aria-label',t().close);const cards=[{id:'photo',title:tx('Photo report · Perrin Beitel Rd','Reporte visual · Perrin Beitel Rd'),time:tx('1 min ago','hace 1 min'),body:tx('Vehicle in moving water. Person inside? <strong>Unsure (54%)</strong>','Vehículo en agua en movimiento. ¿Hay alguien dentro? <strong>Incierto (54%)</strong>'),actions:[['dispatch',tx('Dispatch SAFD','Enviar SAFD'),'orange'],['photo',tx('View photo','Ver foto'),'outline']]},{id:'resident',title:tx('Resident · Vicar Dr','Residente · Vicar Dr'),time:tx('3 min ago','hace 3 min'),body:tx('No dry walking route found. Told to shelter in place on 2nd floor. Elderly, 1 person.','No se encontró ruta seca. Indicación del escenario: permanecer en el segundo piso. Persona mayor, 1 persona.'),actions:[['call',tx('Call resident','Llamar al residente'),'navy'],['rescue',tx('Queue for rescue','Poner en cola de rescate'),'outline']]},{id:'match',title:tx('Match check · Salado Creek','Revisión · Salado Creek'),time:tx('4 min ago','hace 4 min'),body:tx('Family of 5 + wheelchair. Nearest accessible host 0.8 mi. Route safety <strong>71%.</strong>','Familia de 5 + silla de ruedas. Anfitrión accesible a 0.8 mi. Seguridad de ruta <strong>71%.</strong>'),actions:[['match',tx('Approve match','Aprobar alojamiento'),'teal'],['pickup',tx('Send pickup','Enviar transporte'),'outline']]}];document.querySelector('#app').innerHTML=`<div class="coord-shell"><header class="coord-header"><div class="coord-brand"><span class="coord-logo"><svg viewBox="0 0 100 100" aria-hidden="true"><path d="M15 69L40 35 55 56 66 44 85 69Z" fill="#0f1b2d"/><path d="M13 79Q32 69 51 79T87 79" fill="none" stroke="#3b82f6" stroke-width="6" stroke-linecap="round"/></svg></span><div><strong>HighGround</strong><span> · ${tx('Coordinator console','Panel de coordinación')}</span></div></div><div class="coord-badges"><span class="coord-warning">${tx('Demo: Flash Flood Warning · NE Bexar','Demo: Alerta de inundación · NE Bexar')}</span><button id="coord-language" class="coord-demo" aria-label="${tx('Switch language to Spanish','Cambiar idioma a inglés')}"><span lang="en" ${lang==='en'?'class="coord-language-active"':''}>EN</span><span aria-hidden="true"> / </span><span lang="es" ${lang==='es'?'class="coord-language-active"':''}>ES</span></button></div></header><div id="offline" class="offline" role="status" ${navigator.onLine?'hidden':''}>${t().offline}</div><main id="main" class="coord-main" tabindex="-1" aria-label="${tx('Coordinator console — all data is simulated','Panel de coordinación — todos los datos son simulados')}"><h1 class="sr-only">HighGround · ${tx('Coordinator console — demo data','Panel de coordinación — datos demo')}</h1><section class="coord-stats" aria-label="${tx('Simulated summary','Resumen simulado')}">${[[tx('Open requests','Solicitudes abiertas'),'18',''],[tx('Matched to a host','Con alojamiento'),'41','teal'],[tx('Need a human now','Necesitan revisión'),'5','orange'],[tx('Hosts available','Anfitriones disponibles'),'126','']].map(([label,n,c])=>`<div class="coord-stat"><span>${label}</span><strong class="${c}">${n}</strong></div>`).join('')}</section><div class="coord-grid"><section class="coord-map-panel"><div class="coord-map-heading"><h2>${tx('Live map · Beitel & Salado Creek','Mapa en vivo · Beitel y Salado Creek')}</h2><div class="coord-legend"><span><i class="flood"></i>${tx('Flooded','Inundado')}</span><span><i class="host"></i>${tx('Host','Anfitrión')}</span><span><i class="resident"></i>${tx('Resident','Residente')}</span><span><i class="review"></i>${tx('Needs review','Revisar')}</span></div></div>${coordinatorMap()}</section><section class="coord-queue" aria-label="${tx('Simulated review queue','Cola de revisión simulada')}"><div class="coord-queue-heading"><h2>${tx('Needs a human','Necesita revisión')}</h2><span>${tx('AI confidence below 80%','Confianza de IA menor al 80%')}</span></div>${cards.map(card=>`<article class="coord-case ${card.id==='photo'?'priority':''}"><div class="coord-case-heading"><h3>${card.title}</h3><span>${card.time}</span></div><p>${card.body}</p><div class="coord-case-actions">${card.actions.map(([id,label,color])=>`<button class="coord-action ${color}" data-console-action="${id}">${label}</button>`).join('')}</div>${card.actions.some(([id])=>consoleActions.has(id))?`<small class="coord-recorded" role="status">${tx('Demo action recorded · Nothing sent','Acción demo registrada · No se envió nada')}</small>`:''}</article>`).join('')}</section></div><footer class="coord-footer"><p>${tx('Simulation only. Alerts, times, counts, confidence scores, routes and host availability are fictional. No services are contacted.','Solo simulación. Alertas, tiempos, cifras, confianza, rutas y disponibilidad son ficticios. No se contacta a ningún servicio.')}</p><div><button id="demo-info" aria-label="${tx('Demo data: view limitations','Datos demo: ver limitaciones')}">${tx('Demo data','Datos demo')}</button><button id="resident-view">${tx('Resident view','Vista de residente')}</button><button id="coord-privacy">${t().privacy}</button></div></footer></main></div>`;
 document.querySelector('#demo-info').onclick=()=>show(tx('Demo data — not live operations','Datos demo — no son operaciones reales'),`<p class="notice">${tx('Every warning, count, timestamp, host, confidence score and route on this dashboard is fictional. No AI image analysis or route-safety verification has been performed.','Cada alerta, cifra, hora, anfitrión, nivel de confianza y ruta es ficticio. No se ha realizado análisis de imágenes ni verificación de rutas.')}</p><p>${tx('The action buttons simulate a workflow. They cannot call residents, dispatch SAFD, send a vehicle, or reserve accommodation. In immediate danger, call 911.','Los botones simulan un flujo. No llaman a residentes, envían SAFD, vehículos ni reservan alojamiento. En peligro inmediato, llama al 911.')}</p><a href="tel:911">${t().call911}</a>`);
 document.querySelector('#coord-language').onclick=()=>{lang=lang==='en'?'es':'en';render();window.dispatchEvent(new CustomEvent('floodcare-language',{detail:lang}));document.querySelector('#coord-language').focus()};document.querySelector('#resident-view').onclick=()=>go('map');document.querySelector('#coord-privacy').onclick=()=>open('privacy');document.querySelectorAll('[data-console-action]').forEach(b=>b.onclick=()=>{const id=b.dataset.consoleAction;const title=b.textContent;if(id==='photo'){show(tx('Sample image report','Reporte visual de ejemplo'),`<div class="coord-sample-photo"><svg viewBox="0 0 600 240" role="img" aria-label="${tx('Fictional flooded-road illustration, not a submitted photograph','Ilustración ficticia, no una fotografía enviada')}"><rect width="600" height="240" fill="#dce5eb"/><path d="M220 0L90 240h420L380 0" fill="#8197a8"/><path d="M0 130q150-30 300 0t300 0v110H0" fill="#9bbbd2"/><path d="M245 120l20-40h70l25 40v40H245Z" fill="#334155"/><path d="M0 170q150-30 300 0t300 0M0 205q150-30 300 0t300 0" stroke="#dbeafe" stroke-width="4" fill="none"/></svg></div><p class="notice">${tx('Sample illustration only. No photo has been submitted or analyzed. The 54% score in the reference dashboard is fictional, not a measured confidence level.','Solo ilustración de ejemplo. No se ha enviado ni analizado una foto. El 54% del panel es ficticio, no una medición.')}</p>`);return;}show(`${title} — ${tx('demo only','solo demo')}`,`<p class="notice">${tx('This is a simulation. Confirming records this action in this browser session only. It does not contact emergency services, call anyone, send transportation, or confirm a host match.','Esto es una simulación. Confirmar registra la acción solo en esta sesión. No contacta a servicios de emergencia, llama a nadie, envía transporte ni confirma alojamiento.')}</p><p>${tx('Do not use the sample route or shelter-in-place text as instructions for a real emergency. Follow local emergency officials.','No uses la ruta ni el texto del escenario como instrucciones para una emergencia real. Sigue a las autoridades locales.')}</p><div class="actions"><button id="coord-confirm" class="primary">${tx('Record demo action','Registrar acción demo')}</button><button class="outline" data-close>${t().cancel}</button></div>`);document.querySelector('#coord-confirm').onclick=()=>{consoleActions.add(id);dialog.close();render();document.querySelector(`[data-console-action="${id}"]`).focus()}});
}
